CREATE TYPE public.app_role AS ENUM ('user','analyst','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, timezone text NOT NULL DEFAULT 'UTC', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.on_research_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'user'); RETURN NEW; END $$;
CREATE TRIGGER on_research_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.on_research_signup();
CREATE TABLE public.providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL CHECK(kind IN ('etf','spot','perpetual','news')), status text NOT NULL DEFAULT 'unavailable' CHECK(status IN ('unavailable','live','delayed','stale','error')), license_notes text NOT NULL DEFAULT 'Not configured', endpoint text, update_frequency_seconds integer, last_exchange_at timestamptz, last_ingestion_at timestamptz, earliest_coverage_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.providers TO authenticated;
GRANT ALL ON public.providers TO service_role;
ALTER TABLE public.providers ENABLE ROW LEVEL SECURITY;
CREATE POLICY provider_read ON public.providers FOR SELECT TO authenticated USING (true);
CREATE TABLE public.etf_observations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES public.providers(id), ticker text NOT NULL, reporting_date date NOT NULL, net_flow_usd numeric NOT NULL, aum_usd numeric, btc_conversion_price numeric, source_url text NOT NULL, exchange_at timestamptz NOT NULL, ingested_at timestamptz NOT NULL DEFAULT now(), quality text NOT NULL DEFAULT 'unavailable', UNIQUE(provider_id,ticker,reporting_date));
GRANT SELECT ON public.etf_observations TO authenticated;
GRANT ALL ON public.etf_observations TO service_role;
ALTER TABLE public.etf_observations ENABLE ROW LEVEL SECURITY;
CREATE POLICY etf_read ON public.etf_observations FOR SELECT TO authenticated USING (true);
CREATE INDEX etf_reporting_idx ON public.etf_observations(reporting_date DESC,ticker);
CREATE TABLE public.orderbook_observations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, provider_id uuid NOT NULL REFERENCES public.providers(id), symbol text NOT NULL, market text NOT NULL CHECK(market IN ('spot','perpetual')), sequence_id bigint NOT NULL, exchange_at timestamptz NOT NULL, ingested_at timestamptz NOT NULL DEFAULT now(), bids jsonb NOT NULL, asks jsonb NOT NULL, is_snapshot boolean NOT NULL DEFAULT false, quality text NOT NULL, UNIQUE(provider_id,symbol,market,sequence_id));
GRANT SELECT ON public.orderbook_observations TO authenticated;
GRANT ALL ON public.orderbook_observations TO service_role;
ALTER TABLE public.orderbook_observations ENABLE ROW LEVEL SECURITY;
CREATE POLICY depth_read ON public.orderbook_observations FOR SELECT TO authenticated USING (true);
CREATE INDEX depth_time_idx ON public.orderbook_observations(provider_id,market,exchange_at DESC);
CREATE TABLE public.trades (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, provider_id uuid NOT NULL REFERENCES public.providers(id), source_trade_id text NOT NULL, symbol text NOT NULL, market text NOT NULL, price numeric NOT NULL CHECK(price>0), quantity numeric NOT NULL CHECK(quantity>0), aggressor_side text NOT NULL CHECK(aggressor_side IN ('buy','sell','unknown')), exchange_at timestamptz NOT NULL, ingested_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,source_trade_id));
GRANT SELECT ON public.trades TO authenticated;
GRANT ALL ON public.trades TO service_role;
ALTER TABLE public.trades ENABLE ROW LEVEL SECURITY;
CREATE POLICY trades_read ON public.trades FOR SELECT TO authenticated USING (true);
CREATE INDEX trades_time_idx ON public.trades(provider_id,market,exchange_at DESC);
CREATE TABLE public.news_metadata (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES public.providers(id), headline text NOT NULL, publisher text NOT NULL, original_url text NOT NULL, published_at timestamptz NOT NULL, ingested_at timestamptz NOT NULL DEFAULT now(), asset text NOT NULL, category text, claim_type text NOT NULL DEFAULT 'unverified', sentiment text NOT NULL DEFAULT 'neutral', confidence numeric CHECK(confidence BETWEEN 0 AND 1), explanation text, UNIQUE(provider_id,original_url));
GRANT SELECT ON public.news_metadata TO authenticated;
GRANT ALL ON public.news_metadata TO service_role;
ALTER TABLE public.news_metadata ENABLE ROW LEVEL SECURITY;
CREATE POLICY news_read ON public.news_metadata FOR SELECT TO authenticated USING (true);
CREATE TABLE public.derived_signals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, market text NOT NULL, rule_version text NOT NULL, observed_at timestamptz NOT NULL, confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1), evidence jsonb NOT NULL, provenance jsonb NOT NULL, limitations text NOT NULL, alternative_explanations text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.derived_signals TO authenticated;
GRANT ALL ON public.derived_signals TO service_role;
ALTER TABLE public.derived_signals ENABLE ROW LEVEL SECURITY;
CREATE POLICY signals_read ON public.derived_signals FOR SELECT TO authenticated USING (true);
CREATE TABLE public.alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), signal_id uuid REFERENCES public.derived_signals(id), rule text NOT NULL, rule_version text NOT NULL, review_status text NOT NULL DEFAULT 'open' CHECK(review_status IN ('open','reviewing','false_positive','escalated','closed')), analyst_notes text NOT NULL DEFAULT '', observations jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.alerts TO authenticated;
GRANT ALL ON public.alerts TO service_role;
ALTER TABLE public.alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY alerts_own ON public.alerts FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE TABLE public.cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), research_question text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','reviewing','closed')), evidence jsonb NOT NULL DEFAULT '[]', methodology_version text NOT NULL DEFAULT 'FZ-1.0', alternative_explanations text NOT NULL DEFAULT '', limitations text NOT NULL DEFAULT '', conclusion text NOT NULL DEFAULT '', confidence numeric CHECK(confidence BETWEEN 0 AND 1), data_status text NOT NULL DEFAULT 'simulated' CHECK(data_status IN ('simulated','historical','estimated','unavailable')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cases TO authenticated;
GRANT ALL ON public.cases TO service_role;
ALTER TABLE public.cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY cases_own ON public.cases FOR ALL TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE INDEX cases_owner_idx ON public.cases(owner_id,updated_at DESC);
CREATE TABLE public.audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id uuid NOT NULL, resource_id uuid NOT NULL, action text NOT NULL, resource_type text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), details jsonb NOT NULL DEFAULT '{}');
GRANT SELECT ON public.audit_events TO authenticated;
GRANT ALL ON public.audit_events TO service_role;
ALTER TABLE public.audit_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read_own ON public.audit_events FOR SELECT TO authenticated USING(actor_id=auth.uid());
CREATE FUNCTION public.audit_research_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.audit_events(actor_id,resource_id,action,resource_type,details) VALUES(coalesce(auth.uid(),NEW.owner_id),NEW.id,TG_OP,TG_TABLE_NAME,jsonb_build_object('status',coalesce(to_jsonb(NEW)->>'status',to_jsonb(NEW)->>'review_status'))); RETURN NEW; END $$;
CREATE TRIGGER cases_audit AFTER INSERT OR UPDATE ON public.cases FOR EACH ROW EXECUTE FUNCTION public.audit_research_change();
CREATE TRIGGER alerts_audit AFTER INSERT OR UPDATE ON public.alerts FOR EACH ROW EXECUTE FUNCTION public.audit_research_change();
CREATE TABLE public.entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), plan text NOT NULL DEFAULT 'free_explorer' CHECK(plan IN ('free_explorer','pro_trader','research_professional','enterprise')), feature text NOT NULL, usage_limit integer NOT NULL DEFAULT 0 CHECK(usage_limit>=0), expires_at timestamptz, UNIQUE(user_id,feature));
GRANT SELECT ON public.entitlements TO authenticated;
GRANT ALL ON public.entitlements TO service_role;
ALTER TABLE public.entitlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY entitlements_own_read ON public.entitlements FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.subscription_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), provider_subscription_id text UNIQUE, plan text NOT NULL DEFAULT 'free_explorer', status text NOT NULL DEFAULT 'unconfigured', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscription_records TO authenticated;
GRANT ALL ON public.subscription_records TO service_role;
ALTER TABLE public.subscription_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscriptions_own_read ON public.subscription_records FOR SELECT TO authenticated USING(user_id=auth.uid());
COMMENT ON TABLE public.orderbook_observations IS 'Verified sequence-aware observations only. Do not insert demonstration data. Configure bounded retention and storage budgets before enabling high-volume ingestion.';
COMMENT ON TABLE public.etf_observations IS 'Licensed observations only. Net flows do not establish beneficial ownership or institutional intent.';